import ast, sys
from pathlib import Path
for f in ["workflow/launch.py","workflow/interactive.py","workflow/registry.py","workflow/scaffold.py","workflow/sessions.py","workflow/test_portable.py","workflow/test_lanes.py","workflow/test_interactive.py","workflow/test_sessions.py","workflow/test_feature_launch.py","workflow/automatic.py"]:
    src = Path(f).read_text(); tree = ast.parse(src)
    names = set()
    for node in ast.walk(tree):
        if isinstance(node,(ast.Import,ast.ImportFrom)):
            for a in node.names: names.add((a.asname or a.name).split(".")[0])
    used = {n.id for n in ast.walk(tree) if isinstance(n,ast.Name)} | {n.value.id for n in ast.walk(tree) if isinstance(n,ast.Attribute) and isinstance(n.value,ast.Name)}
    unused = sorted(n for n in names - used if n not in {"annotations"})
    print(f, unused)
EOF

